import{_ as t,o as i,c as o,a5 as a}from"./chunks/framework.BEZBAInb.js";const g=JSON.parse('{"title":"KonadoScript Editor","description":"","frontmatter":{"title":"KonadoScript Editor","order":5},"headers":[],"relativePath":"en/latest/tutorial/core/ks-editor-highlighter.md","filePath":"en/latest/tutorial/core/ks-editor-highlighter.md","lastUpdated":1788455378000}'),n={name:"en/latest/tutorial/core/ks-editor-highlighter.md"};function r(s,e,d,l,c,h){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="built-in-godot-konadoscript-editor" tabindex="-1">Built-in Godot KonadoScript Editor <a class="header-anchor" href="#built-in-godot-konadoscript-editor" aria-label="Permalink to &quot;Built-in Godot KonadoScript Editor&quot;">​</a></h1><p>After enabling the Konado plugin, double-clicking a <code>.ks</code> file in the FileSystem dock opens it in Godot&#39;s Script workspace, just like a <code>.gd</code> file. KonadoScript uses Godot&#39;s native code editor and document tabs instead of a bottom dock.</p><h2 id="editing-features" tabindex="-1">Editing Features <a class="header-anchor" href="#editing-features" aria-label="Permalink to &quot;Editing Features&quot;">​</a></h2><ul><li>Edit <code>.ks</code>, <code>.gd</code>, and other scripts together in Godot&#39;s script document tabs</li><li>While editing <code>.ks</code>, replace the upper-left script list with the component and command tree; on first open, the component and branch regions use a 2:1 height ratio, the sliding toggle in the header expands or collapses every group while retaining the top-level categories, selecting an entry inserts its statement, and the lower member outline remains available for branch navigation</li><li>Open either the <code>2.4 LTS</code> or <code>latest</code> documentation in the editor locale from Online Docs; Godot&#39;s API help search is hidden while editing <code>.ks</code> because it does not support KonadoScript, and the original interface returns when another script language is active</li><li>When language variants exist for the current script, use the selector beside Online Docs to switch directly between Default and the discovered localized scripts</li><li>Let Godot manage undo and redo, unsaved state, external changes, and close confirmation</li><li>Use the Script Editor&#39;s find and replace, go to line, zoom, bookmarks, and shortcuts</li><li>Create a KonadoScript with valid starter content from the FileSystem Create menu</li><li>Browse <code>branch</code> declarations in the member outline; branches, variables, and signals support Go to Definition, Find References, and safe rename</li><li>Ctrl-click (Command-click on macOS) a background, actor, state, motion, BGM, sound effect, voice, camera setup, or <code>jump</code> path to open its actual scene, resource, or target KonadoScript; choose from a target list when a name is ambiguous</li><li>Hover commands and resource identifiers to inspect signatures, purpose, resolved paths, or unresolved status; an underline appears only when a real navigation target exists</li><li>Use the context menu to format a document or selection, apply fixes, go to definitions, find references, and rename safely; cross-file resource renames show a change preview first</li><li>Auto-indent conditional and full-screen text blocks using Godot&#39;s indentation settings</li><li>Save directly to the original <code>.ks</code> file and refresh the runtime <code>KonadoShot</code> compiled by the resource loader</li></ul><h2 id="highlighting-and-completion" tabindex="-1">Highlighting and Completion <a class="header-anchor" href="#highlighting-and-completion" aria-label="Permalink to &quot;Highlighting and Completion&quot;">​</a></h2><p><code>KonadoScriptSyntaxHighlighter</code> is built on Godot&#39;s <code>EditorSyntaxHighlighter</code> and is registered with the Script Editor when the plugin starts. Highlighting and completion share <code>KonadoScriptLanguageCatalog</code>, while valid keywords come from the parser&#39;s <code>KonadoScriptToken.KEYWORDS</code>. Automated checks keep both sources aligned.</p><p>Completion offers commands, subcommands, insertable statement templates, and the 2.8 named parameters valid for the current statement, while omitting parameters already present. It also indexes project resources for KonadoScript paths, actors, states, motions, backgrounds, audio, and cameras. States and custom motions are filtered for the selected actor, dialogue voice completion handles quoted text containing spaces, and branches, variables, and signals from the current document are suggested immediately. Named parameters have dedicated highlighting, while the authoritative compiler validates their types, ranges, conflicts, and duplicate IDs. Highlighting expressions are compiled once, and each line records only color transitions.</p><p>The default highlighting resource is located at:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>res://addons/konado/editor/script_editor/konado_script_highlighter.tres</span></span></code></pre></div><p>Other <code>CodeEdit</code> controls can also instantiate the highlighter directly:</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set_syntax_highlighter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">KonadoScriptSyntaxHighlighter</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())</span></span></code></pre></div><h2 id="live-diagnostics" tabindex="-1">Live Diagnostics <a class="header-anchor" href="#live-diagnostics" aria-label="Permalink to &quot;Live Diagnostics&quot;">​</a></h2><p>After a short typing pause, Godot asks the KonadoScript language bridge to run lexical, syntax, and semantic analysis without generating a runtime <code>KonadoShot</code>. Errors and warnings appear on the relevant source lines and in the Script Editor&#39;s built-in problems panels, in Chinese or English according to the Godot editor language. Independent errors on multiple lines are reported together. Checks cover trailing arguments, invalid numeric and Boolean values, invalid jump paths, unknown resource IDs, missing target files, actor lifecycle errors, and localized-script structure; malformed input cannot stall live analysis.</p><p>Hover an error range to open a diagnostic card whose width and height adapt to its contents. A diagnostic may offer up to three <strong>Try</strong> actions ranked by likelihood. Alternatives requiring a decision are excluded from <strong>Apply All Safe Quick Fixes</strong>. Diagnostics without an automatic edit link to the relevant resource configuration or documentation. Each edit is one undoable operation and preserves carets, selections, multiple carets, folds, and scroll position.</p><p>Click a problem to jump to the relevant location. Existing files remain open and repairable even when they contain syntax errors. The resource loader performs the authoritative compilation after saving, so live diagnostics do not replace the final load result.</p><h2 id="runtime-debugging" tabindex="-1">Runtime Debugging <a class="header-anchor" href="#runtime-debugging" aria-label="Permalink to &quot;Runtime Debugging&quot;">​</a></h2><p>Use Godot breakpoints to control KonadoScript execution. When a breakpoint is reached, the debugger opens the matching <code>.ks</code> line and shows the current shot, node, persistent variables, and temporary variables. The debugger tab provides Continue, Step, and Pause at next line actions. Editor debugging sessions are not enabled in release exports.</p><h2 id="shortcuts" tabindex="-1">Shortcuts <a class="header-anchor" href="#shortcuts" aria-label="Permalink to &quot;Shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Windows / Linux</th><th>macOS</th></tr></thead><tbody><tr><td>Save</td><td><code>Ctrl+S</code></td><td><code>Command+S</code></td></tr><tr><td>Close current tab</td><td><code>Ctrl+W</code></td><td><code>Command+W</code></td></tr><tr><td>Find</td><td><code>Ctrl+F</code></td><td><code>Command+F</code></td></tr><tr><td>Find and replace</td><td><code>Ctrl+H</code></td><td><code>Command+Option+F</code></td></tr><tr><td>Go to line</td><td><code>Ctrl+L</code></td><td><code>Command+L</code></td></tr></tbody></table>',19)])])}const u=t(n,[["render",r]]);export{g as __pageData,u as default};
